-- B6L CONNECT: execute on the existing D1 database after reviewing backups.
CREATE TABLE IF NOT EXISTS discovery_sources (id INTEGER PRIMARY KEY, name TEXT NOT NULL, feed_url TEXT NOT NULL UNIQUE, category TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, last_checked_at TEXT, last_error TEXT);
CREATE TABLE IF NOT EXISTS opportunities (id INTEGER PRIMARY KEY, source_id INTEGER NOT NULL REFERENCES discovery_sources(id), external_id TEXT NOT NULL, title TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', url TEXT NOT NULL, category TEXT NOT NULL, published_at TEXT, expires_at TEXT, verified_at TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','expired','rejected')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(source_id,external_id));
CREATE INDEX IF NOT EXISTS idx_opportunities_status ON opportunities(status,created_at);
CREATE TABLE IF NOT EXISTS connect_users (id INTEGER PRIMARY KEY, artist_id INTEGER UNIQUE, identity_subject TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS connect_messages (id INTEGER PRIMARY KEY, sender_id INTEGER NOT NULL REFERENCES connect_users(id), recipient_id INTEGER NOT NULL REFERENCES connect_users(id), body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 4000), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, read_at TEXT);
CREATE INDEX IF NOT EXISTS idx_connect_messages_recipient ON connect_messages(recipient_id,created_at);
CREATE TABLE IF NOT EXISTS connect_notifications (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES connect_users(id), opportunity_id INTEGER REFERENCES opportunities(id), type TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, read_at TEXT, UNIQUE(user_id,opportunity_id,type));
